-- Existing unscoped subjects remain available. New college subjects belong to a semester.
ALTER TABLE subjects ADD COLUMN college_semester_id CHAR(36) NULL, ADD COLUMN semester_scope VARCHAR(36) GENERATED ALWAYS AS (COALESCE(college_semester_id,'')) STORED, ADD INDEX idx_subject_org(org_id), DROP INDEX org_id, ADD UNIQUE KEY uq_subject_scope(org_id,semester_scope,name), ADD FOREIGN KEY(college_semester_id) REFERENCES grades(id);
ALTER TABLE course_materials ADD COLUMN assessment_only BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE assessments ADD COLUMN due_at DATETIME(3) NULL, ADD COLUMN question_material_id CHAR(36) NULL, ADD FOREIGN KEY(question_material_id) REFERENCES course_materials(id) ON DELETE SET NULL;
CREATE TABLE course_reference_links (id CHAR(36) PRIMARY KEY,course_id CHAR(36) NOT NULL,title VARCHAR(160) NOT NULL,url VARCHAR(2000) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE college_marks (id CHAR(36) PRIMARY KEY,course_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,label VARCHAR(120) NOT NULL,score DECIMAL(7,2) NOT NULL,max_score DECIMAL(7,2) NOT NULL,feedback TEXT NOT NULL,graded_by CHAR(36) NOT NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(course_id,user_id,label),FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(graded_by) REFERENCES users(id),CHECK(score>=0 AND score<=max_score AND max_score>0)) ENGINE=InnoDB;
